
clear all, close all,

load('Q1data.mat','x','labels');

p = [0.35,0.65];
lambda = [0 1;1 0];


mu(:,1) = [-0.5;-0.5;-0.5;-0.5];
mu(:,2) = [1;1;1;1];

% AI-assisted: Naive Bayes covariance assumption
Sigma(:,:,1) = diag([0.5,0.25,0.25,0.5]);
Sigma(:,:,2) = diag([1,2,1,3]);


g1 = mvnpdf(x',mu(:,1)',Sigma(:,:,1))';
g2 = mvnpdf(x',mu(:,2)',Sigma(:,:,2))';

discriminantScoresERM = log(g2./g1);

[Pfp,Ptp,Perror,thresholdList] = ...
    ROCcurve(discriminantScoresERM,labels);

Pfn = 1-Ptp;


% AI-assisted: Calculate error using the true class priors
PerrorWeighted = p(1)*Pfp + p(2)*Pfn;

% Find minimum error using MATLAB min
[minPerror,indexMin] = min(PerrorWeighted);

% AI-assisted: Convert log threshold to gamma
gammaEmpirical = exp(thresholdList(indexMin));


gammaTheoretical = (lambda(2,1)-lambda(1,1)) / ...
                   (lambda(1,2)-lambda(2,2)) * p(1)/p(2);

PfpMin = Pfp(indexMin);
PtpMin = Ptp(indexMin);
PfnMin = Pfn(indexMin);

fprintf('\nQuestion 1 - Part B\n'); %[output:92e31553]
fprintf('Empirical optimal gamma: %.6f\n',gammaEmpirical); %[output:37bc9688]
fprintf('Theoretical optimal gamma: %.6f\n',gammaTheoretical); %[output:2bd2f21b]
fprintf('Minimum P(error): %.6f\n',minPerror); %[output:24af74c9]
fprintf('P(False Positive): %.6f\n',PfpMin); %[output:4542bfe4]
fprintf('P(True Positive): %.6f\n',PtpMin); %[output:51e37a64]
fprintf('P(False Negative): %.6f\n',PfnMin); %[output:70172106]

figure(1), clf, %[output:3c830bbc]
plot(Pfp,Ptp,'*m'), %[output:3c830bbc]
hold on, %[output:3c830bbc]
plot(PfpMin,PtpMin,'ro','MarkerSize',12,'LineWidth',2), %[output:3c830bbc]
xlabel('P(False+)'), %[output:3c830bbc]
ylabel('P(True+)'), %[output:3c830bbc]
title('ROC Curve for Naive Bayes Classifier'), %[output:3c830bbc]
legend('ROC Curve','Minimum P(error)','Location','southeast'), %[output:3c830bbc]
grid on, %[output:3c830bbc]

exportgraphics(gca,'Q1_B_ROC.png','Resolution',300); %[output:3c830bbc]


A = load('Q1_A2_results.mat');

% AI-assisted: Compare empirical minimum errors
PerrorA = p(1)*A.Pfp + p(2)*A.Pfn;
minPerrorA = min(PerrorA);

fprintf('\nComparison with Part A\n'); %[output:402edaf9]
fprintf('Part A minimum P(error): %.6f\n',minPerrorA); %[output:900f4810]
fprintf('Part B minimum P(error): %.6f\n',minPerror); %[output:1cd6cda0]
fprintf('Difference (B - A): %.6f\n',minPerror-minPerrorA); %[output:82d8e5f2]

% AI-assisted: Plot both ROC curves on the same graph
figure(2), clf, %[output:2b5663e8]
plot(A.Pfp,A.Ptp,'b','LineWidth',2), %[output:2b5663e8]
hold on, %[output:2b5663e8]
plot(Pfp,Ptp,'m','LineWidth',2), %[output:2b5663e8]
plot(PfpMin,PtpMin,'ro','MarkerSize',10,'LineWidth',2), %[output:2b5663e8]
xlabel('P(False+)'), %[output:2b5663e8]
ylabel('P(True+)'), %[output:2b5663e8]
title('ROC Comparison: True Model vs Naive Bayes'), %[output:2b5663e8]
legend('Part A - True Model','Part B - Naive Bayes', ... %[output:2b5663e8]
       'NB Minimum P(error)','Location','southeast'), %[output:2b5663e8]
xlim([0 1]), %[output:2b5663e8]
ylim([0 1]), %[output:2b5663e8]
grid on, %[output:2b5663e8]

exportgraphics(gca,'Q1_B_vs_A_ROC.png','Resolution',300); %[output:2b5663e8]

save('Q1_B_results.mat','Pfp','Ptp','Pfn', ...
     'thresholdList','gammaEmpirical','gammaTheoretical', ...
     'minPerror','PfpMin','PtpMin');

function [Pfp,Ptp,Perror,thresholdList] = ROCcurve(discriminantScores,labels)

[sortedScores,ind] = sort(discriminantScores,'ascend');

thresholdList = [min(sortedScores)-eps, ...
    (sortedScores(1:end-1)+sortedScores(2:end))/2, ...
    max(sortedScores)+eps];

for i = 1:length(thresholdList)

    tau = thresholdList(i);
    decisions = (discriminantScores >= tau);

    Ptn(i) = length(find(decisions==0 & labels==0)) ...
        /length(find(labels==0));

    Pfp(i) = length(find(decisions==1 & labels==0)) ...
        /length(find(labels==0));

    Ptp(i) = length(find(decisions==1 & labels==1)) ...
        /length(find(labels==1));

    Perror(i) = sum(decisions~=labels)/length(labels);

end

end


